-- Scaffold and snapshot generated by drizzle-kit generate --custom --name=observation_upstream_receipts.
-- PostgreSQL function only; no table changes or stored-data conversion.
-- Captured provenance is authoritative: never join the mutable source catalogue.
DROP FUNCTION conditions.flow_credit(text, jsonb);
--> statement-breakpoint
CREATE FUNCTION conditions.flow_credit(native_source text, supplied jsonb, upstream jsonb DEFAULT '[]'::jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
  WITH identity AS (
    SELECT COALESCE(NULLIF(supplied->>'parentSourceId',''), native_source) AS id,
      COALESCE(NULLIF(supplied->>'name',''), supplied->>'provider') AS name
  ), credits AS (
    SELECT 0 AS ord, jsonb_strip_nulls(jsonb_build_object(
      'sourceId', identity.id,
      'name', identity.name,
      'url', supplied->>'url',
      'licensing', supplied->'licensing',
      'attributionText', supplied->>'provider',
      'publisher', supplied->'publisher'
    )) AS credit FROM identity WHERE identity.name IS NOT NULL
    UNION ALL
    SELECT 1, jsonb_strip_nulls(jsonb_build_object(
      'sourceId', identity.id,
      'name', identity.name || ' – ' || (u.value->>'publisher'),
      'url', supplied->>'url',
      'licensing', u.value->'licensing',
      'attributionText', u.value->>'attribution',
      'publisher', jsonb_build_object('name', u.value->>'publisher')
    )) FROM identity CROSS JOIN LATERAL jsonb_array_elements(COALESCE(upstream, '[]'::jsonb)) u
      WHERE NULLIF(u.value->>'publisher','') IS NOT NULL AND identity.name IS NOT NULL
  ) SELECT COALESCE(jsonb_agg(credit ORDER BY ord, credit::text), '[]'::jsonb)
    FROM (SELECT DISTINCT ord, credit FROM credits) c;
$$;
